                    },
                    "name": {
                        "type": "string",
                        "description": "Sometimes, you just need to call your request 'Bob'. Postman will let you do that, and store the name you give in this field."
                    },
                    "dataMode": {
                        "type": "string",
                        "enum": [
                            "raw",
                            "urlencoded",
                            "params"
                        ],
                        "description": "A request can have a specific data mode, and Postman supports three."
                    },
                    "data": {
                        "type": "array",
                        "description": "Data is an array of key-values that the request goes with. POST data, PUT data, etc goes here.",
                        "items": {
                            "type": "object",
                            "properties": {
                                "key": {
                                    "type": "string"
                                },
                                "value": {
                                    "type": "string"
                                },
                                "enabled": {
                                    "type": "boolean"
                                },
                                "type": {
                                    "enum": [
                                        "file",
                                        "text"
                                    ]
                                }
                            }
                        }
                    },
                    "descriptionFormat": {
                        "oneOf": [
                            {
                                "type": "string",
                                "enum": [
                                    "html",
                                    "markdown"
                                ]
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "A request can have an associated description text. Since description is meant to be long, it can be in either ``html`` or ``markdown`` formats. This field specifies that format."
                    },
                    "description": {
                        "type": "string",
                        "description": "The description of this request. Can be as long as you want. Postman also supports two formats for your description, ``markdown`` and ``html``."
                    },
                    "headers": {
                        "type": "string",
                        "description": "No HTTP request is complete without its headers, and the same is true for a Postman request. This field contains all the HTTP Headers in a raw string format."
                    },
                    "method": {
                        "type": "string",
                        "enum": [
                            "GET",
                            "PUT",
                            "POST",
                            "PATCH",
                            "DELETE",
                            "COPY",
                            "HEAD",
                            "OPTIONS",
                            "LINK",
                            "UNLINK",
                            "PURGE",
                            "LOCK",
                            "UNLOCK",
                            "PROPFIND",
                            "VIEW"
                        ],
                        "description": "The HTTP method associated with this request."
                    },
                    "pathVariables": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "object"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "A Postman request allows you to use Path Variabled in a request, e.g: ``{{url}}``. This field stores these variables."
                    },
                    "url": {
                        "type": "string",
                        "description": "Contains the complete URL for this request, along with the path variables, if any."
                    },
                    "preRequestScript": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "In some use cases, it's necessary to run a bit of code or perform some tasks before sending a request. Postman implements this feature by the use of this field. Any code written to this field is run before running a request."
                    },
                    "tests": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            }
                        ],
                        "description": "Postman allows you to define a script that is run after executing the request, which may act on the response. Such a script is stored in this field."
                    },
                    "time": {
                        "type": "number",
                        "multipleOf": 1,
                        "description": "The timestamp for this request."
                    },
                    "responses": {
                        "type": "array",
                        "description": "A Postman request can have multiple responses associated with it. These responses are stored in this field.",
                        "items": {
                            "title": "Response",
                            "description": "A response represents an HTTP response.",
                            "properties": {
                                "request": {
                                    "oneOf": [
                                        {
                                            "type": "string"
                                        },
                                        {
                                            "type": "object"
                                        }
                                    ],
                                    "description": "A response is associated with a request. This fields contains the UUID of the request corresponding to this response."
                                },
                                "id": {
                                    "type": "string",
                                    "description": "In order to unambiguously identify a response, Postman assigns a UUID to it, and stores it in this field."
                                },
                                "name": {
                                    "type": "string",
                                    "description": "A response can have a friendly name, which goes here."
                                },
                                "status": {
                                    "type": "string",
                                    "description": ""
                                },
                                "responseCode": {
                                    "type": "object",
                                    "properties": {
                                        "code": {
                                            "type": "number",
                                            "description": "The numeric HTTP response code."
                                        },
                                        "name": {
                                            "type": "string",
                                            "description": "The textual HTTP response code."
                                        },
                                        "detail": {
                                            "type": "string",
                                            "description": "Detailed explanation of the response code."
                                        }
                                    },
                                    "required": [
                                        "code",
                                        "name"
                                    ]
                                },
                                "time": {
                                    "oneOf": [
                                        {
                                            "type": "string"
                                        },
                                        {
                                            "type": "number"
                                        }
                                    ],
                                    "description": "The time taken by this particular HTTP transaction to complete is stored in this field."
                                },
                                "headers": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "name": {
                                                "type": "string",
                                                "description": "Some headers can have names associated with them, which are stored in this field."
                                            },
                                            "key": {
                                                "type": "string",
                                                "description": "The left hand side (LHS) or 'key' of the header."
                                            },
                                            "value": {
                                                "type": "string",
                                                "description": "Value of the header, or the right hand side (RHS)."
                                            },
                                            "description": {
                                                "type": "string",
                                                "description": "An optional description about the header."
                                            }
                                        },
                                        "required": [
                                            "name",
                                            "key",
                                            "value"
                                        ]
                                    }
                                },
                                "cookies": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "domain": {
                                                "type": "string",
                                                "description": "The domain for which this cookie is valid."
                                            },
                                            "expirationDate": {
                                                "type": "number",
                                                "description": "The timestamp of the time when the cookie expires."
                                            },
                                            "hostOnly": {
                                                "type": "boolean",
                                                "description": "Indicates if this cookie is Host Only."
                                            },
                                            "httpOnly": {
                                                "type": "boolean",
                                                "description": "Indicates if this cookie is HTTP Only."
                                            },
                                            "name": {
                                                "type": "string",
                                                "description": "This is the name of the Cookie."
                                            },
                                            "path": {
                                                "type": "string",
                                                "description": "The path associated with the Cookie."
                                            },
                                            "secure": {
                                                "type": "boolean",
                                                "description": "Indicates if the 'secure' flag is set on the Cookie."
                                            },
                                            "session": {
                                                "type": "boolean",
                                                "description": "True if the cookie is a session cookie."
                                            },
                                            "storeId": {
                                                "type": "string",
                                                "description": "The ID of the cookie store containing this cookie."
                                            },
                                            "value": {
                                                "type": "string",
                                                "description": "The value of the Cookie."
                                            },
                                            "expires": {
                                                "type": "string",
                                                "description": "Human readable expiration time."
                                            }
                                        },
                                        "required": [
                                            "domain",
                                            "expirationDate",
                                            "hostOnly",
                                            "httpOnly",
                                            "name",
                                            "path",
                                            "secure",
                                            "session",
                                            "storeId",
                                            "value",
                                            "expires"
                                        ]
                                    }
                                },
                                "mime": {
                                    "type": "string",
                                    "description": "Mimetype of the response."
                                },
                                "text": {
                                    "type": "string",
                                    "description": "The raw text of the response."
                                },
                                "language": {
                                    "type": "string",
                                    "enum": [
                                        "html",
                                        "javascript",
                                        "xml"
                                    ],
                                    "description": "The language associated with the response."
                                },
                                "rawDataType": {
                                    "type": "string",
                                    "description": "The data type of the raw response."
                                }
                            },
                            "required": [
                                "id",
                                "responseCode",
                                "request"
                            ]
                        }
                    },
                    "rawModeData": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
                            },
                            {
                                "type": "array"
                            }
                        ],
                        "description": "Contains the raw data (parameters) that Postman sends to the server"
                    }
                },
                "required": [
                    "id",
                    "method",
                    "url",
                    "headers",
                    "name"
                ]
            }
        }
    },
    "required": [
        "id",
        "name",
        "order",
        "requests"
    ]
}

{
    "definitions": {
        "kindle": {
            "$schema": "http://json-schema.org/draft-04/schema",
            "definitions": {
                "authors": {
                    "description": "Authors of kindle - API Author",
                    "example": [
                        "メーブ",
                        "恵広史"
                    ],
                    "items": {
                        "type": [
                            "string"
                        ]
                    },
                    "minItems": 1,
                    "readOnly": true,
                    "type": [
                        "array",
                        "null"
                    ],
                    "_uniqueItems": true
                },
                "created_at": {
                    "description": "when kindle was created",
                    "example": "2015-01-01T00:00:00.000Z",
                    "format": "date-time",
                    "type": [
                        "string"
                    ]
                },
                "id": {
                    "description": "ASIN code (unique identifier)",
                    "example": "B01N3PNATY",
                    "pattern": "^[0-9A-Z]{10}$",
                    "readOnly": true,
                    "type": [
                        "string"
                    ]
                },
                "identity": {
                    "$ref": "#/definitions/kindle/definitions/id"
                },
                "images": {
                    "description": "Images of kindle",
                    "properties": {
                        "large": {
                            "description": "Image (h500,w336) - API ImageSet/LargeImage/URL",
                            "example": "https://images-fe.ssl-images-amazon.com/images/G/09/nav2/dp/no-image-no-ciu.gif",
                            "format": "uri",
                            "pattern": "^https://images-fe\\.ssl-images-amazon\\.com/images/.*?(no-image-no-ciu)?\\.(gif|jpg)$",
                            "readOnly": true,
                            "type": [
                                "string"
                            ]
                        },
                        "medium": {
                            "description": "Image (h160,w108) - API ImageSet/MediumImage/URL",
                            "example": "https://images-fe.ssl-images-amazon.com/images/I/51ZcS0q0-BL._SL160_.jpg",
                            "format": "uri",
                            "pattern": "^https://images-fe\\.ssl-images-amazon\\.com/images/.*?(no-image-no-ciu)?\\._SL160_\\.(gif|jpg)$",
                            "readOnly": true,
                            "type": [
                                "string"
                            ]
                        },
                        "small": {
                            "description": "Image (h75,w50) - API ImageSet/SmallImage/URL",
                            "example": "https://images-fe.ssl-images-amazon.com/images/I/51ZcS0q0-BL._SL75_.jpg",
                            "format": "uri",
                            "pattern": "^https://images-fe\\.ssl-images-amazon\\.com/images/.*?(no-image-no-ciu)?\\._SL75_\\.(gif|jpg)$",
                            "readOnly": true,
                            "type": [
                                "string"
                            ]
                        },
                        "swatch": {
                            "description": "Image (h30,w20) - API ImageSet/SwatchImage/URL",
                            "example": "https://images-fe.ssl-images-amazon.com/images/I/51ZcS0q0-BL._SL30_.jpg",
                            "format": "uri",
                            "pattern": "^https://images-fe\\.ssl-images-amazon\\.com/images/.*?(no-image-no-ciu)?\\._SL30_\\.(gif|jpg)$",
                            "readOnly": true,
                            "type": [
                                "string"
                            ]
                        },
                        "tiny": {
                            "description": "Image (h110,w74) - API ImageSet/TinyImage/URL",
                            "example": "https://images-fe.ssl-images-amazon.com/images/I/51ZcS0q0-BL._SL110_.jpg",
                            "format": "uri",
                            "pattern": "^https://images-fe\\.ssl-images-amazon\\.com/images/.*?(no-image-no-ciu)?\\._SL110_\\.(gif|jpg)$",
                            "readOnly": true,
                            "type": [
                                "string"
                            ]
                        }
                    },
                    "readOnly": true,
                    "type": [
                        "object",
                        "null"
                    ]
                },
                "published_at": {
                    "description": "when kindle was released (API PublicationDate)",
                    "example": "2015-01-01",
                    "pattern": "^[12][0-9]{3}-[0-1][0-9]-[0-3][0-9]$",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "publisher": {
                    "description": "Publisher of kindle - API Publisher",
                    "example": "講談社",
                    "readOnly": true,
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "title": {
                    "description": "Title of kindle",
                    "example": "バトルスタディーズ（８） (モーニングコミックス)",
                    "readOnly": true,
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "updated_at": {
                    "description": "when kindle was updated",
                    "example": "2015-01-01T00:00:00.000Z",
                    "format": "date-time",
                    "type": [
                        "string"
                    ]
                },
                "url": {
                    "description": "Detail page URL of kindle - API DetailPageURL",
                    "example": "https://www.amazon.co.jp/o/ASIN/B00EI2Y81I/habitec-22/",
                    "format": "uri",
                    "pattern": "^https://(www\\.)?amazon\\.co\\.jp/o/ASIN/[0-9A-Z]{10}/habitec-22/?$",
