            "default": "no"
        },
        "title": {
            "description": "Title - exactly as published in the original language. Markdown accepted.",
            "type": "string"
        },
        "subtitle": {
            "type": [
                "string",
                "null"
            ]
        },
        "publication_lang": {
            "type": [
                "string",
                "null"
            ],
            "default": "en"
        },
        "abstract": {
            "_uniqueItems": true,
            "type": "array",
            "description": "Scientific abstract. Markdown accepted.",
            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "@language": {
                        "type": "string",
