            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "@language": {
                        "type": "string",
                        "default": "en"
                    },
                    "@value": {
                        "type": [
                            "string",
                            "null"
                        ]
                    }
                }
            }
        },
        "programme": {
            "title": "Programmes",
            "description": "Select programmes affiliated with the publication",
            "type": "array",
            "additionalItems": false,
            "_uniqueItems": true,
            "items": {
                "type": "string",
                "enum": [
                    "Fram Strait",
                    "Biodiversity",
                    "Environmental management",
                    "Environmental pollutants",
                    "Geology and geophysics",
                    "Oceans and sea ice",
                    "Arctic ocean",
                    "Svalbard",
                    "Antarctic",
                    "Ny-\u00c5lesund"
                ]
            }
        },
        "publication_type": {
            "enum": [
                "peer-reviewed",
                "editorial",
                "review",
                "correction",
                "book",
                "in-book",
                "poster",
                "report",
                "in-report",
                "abstract",
                "phd",
                "master",
                "map",
                "proceedings",
                "popular",
                "other"
            ]
        },
        "type": {
            "enum": [
                "peer-reviewed",
                "editorial",
                "review",
                "correction",
                "book",
                "in-book",
                "poster",
                "report",
                "in-report",
                "abstract",
                "phd",
                "master",
                "map",
                "proceedings",
                "popular",
                "other"
            ]
        },
        "state": {
            "enum": [
                "submitted",
                "accepted",
                "published"
            ],
            "default": "published"
        },
        "locations": {
            "type": "array",
            "_uniqueItems": true,
            "additionalItems": true,
            "items": {
                "type": "object",
                "additionalProperties": true,
                "properties": {
                    "placename": {
                        "type": "string"
                    },
                    "area": {
                        "type": "string"
                    },
                    "country": {
                        "description": "[Country code](http://en.wikipedia.org/wiki/ISO_3166-1_alpha-2), use 'NO' for Norway, including Svalbard and Jan Mayen, Bouvet\u00f8ya, and Peter I \u00d8y. 'AQ' = Antarctica and 'XZ' = International waters",
                        "type": [
                            "string",
                            "null"
                        ],
                        "pattern": "^(([A-Z]|[a-z]){2})$"
                    },
                    "hemisphere": {
                        "description": "Hemisphere: N or S",
