            }
        },
        "published": {
            "type": [
                "string",
                "null"
            ],
            "format": "/^[0-9]{4}/"
        },
        "printed": {
            "type": [
                "string",
                "null"
            ],
            "format": "/^[0-9]{4}/"
        },
        "volume": {
            "type": [
                "string",
                "null"
            ]
        },
        "issue": {
            "type": [
                "string",
                "null"
            ]
        },
        "suppl": {
            "type": [
                "string",
                "null"
            ]
        },
        "art_no": {
            "type": [
                "string",
                "null"
            ]
        },
        "page_count": {
            "type": [
                "string",
                "null"
            ]
        },
        "journal": {
            "title": "Journal",
            "description": "Peer-reviewed journal",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "type": "string"
                },
                "name": {
                    "type": "string"
                },
                "np_series": {
                    "type": "string"
                },
                "series": {
                    "type": "string"
                },
                "series_no": {
                    "type": "string"
                }
            }
        },
        "conference": {
            "title": "Conference",
            "description": "For abstracts and proceedings",
