                        "examples": [
                            "http",
                            "ftp",
                            "file"
                        ]
                    },
                    "format": {
                        "type": "string",
                        "title": "Format",
                        "description": "The data format.",
                        "examples": [
                            "csv",
                            "ods",
                            "xls"
                        ]
                    },
                    "encoding": {
                        "type": "string",
                        "title": "Encoding",
                        "description": "The encoding of the table.",
                        "examples": [
                            "utf-8",
                            "iso-89951"
                        ]
                    },
                    "schema": {
                        "type": "string",
                        "title": "Schema",
                        "description": "An explanation about the purpose of this instance.",
                        "examples": [
                            "table-schema"
                        ]
                    },
                    "errors": {
                        "type": "array",
                        "title": "Errors",
                        "items": {
                            "type": "object",
                            "required": [
