                            "type": "string"
                        }
                    }
                },
                "noauth": {},
                "oauth1": {
                    "type": "object",
                    "properties": {
                        "consumerKey": {
                            "type": "string"
                        },
                        "consumerSecret": {
                            "type": "string"
                        },
                        "token": {
                            "type": "string"
                        },
                        "tokenSecret": {
                            "type": "string"
                        },
                        "signatureMethod": {
                            "type": "string"
                        },
                        "timeStamp": {
                            "type": "string"
                        },
                        "nonce": {
                            "type": "string"
                        },
                        "version": {
                            "type": "string"
                        },
                        "realm": {
                            "type": "string"
                        },
                        "encodeOAuthSign": {
                            "type": "string"
                        }
                    }
                },
                "oauth2": {
                    "type": "object",
                    "properties": {
                        "addTokenTo": {
                            "type": "string"
                        },
                        "callBackUrl": {
                            "type": "string"
                        },
                        "authUrl": {
                            "type": "string"
                        },
                        "accessTokenUrl": {
                            "type": "string"
