{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "JSON schema for coffeelint.json files",
    "definitions": {
        "base": {
            "type": "object",
            "properties": {
                "level": {
                    "description": "Determines the error level",
                    "type": "string",
                    "enum": [
                        "warn",
                        "error",
                        "ignore"
                    ]
                },
                "name": {
                    "type": "string"
                }
            }
        }
    },
    "type": "object",
    "properties": {
        "arrow_spacing": {
            "description": "This rule checks to see that there is spacing before and after the arrow operator that declares a function.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "camel_case_classes": {
            "description": "This rule mandates that all class names are CamelCased. Camel casing class names is a generally accepted way of distinguishing constructor functions - which require the 'new' prefix to behave properly - from plain old functions.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "coffeescript_error": {
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "colon_assignment_spacing": {
            "description": "This rule checks to see that there is spacing before and after the colon in a colon assignment (i.e., classes, objects).",
            "properties": {
                "spacing": {
                    "type": "object",
                    "properties": {
                        "left": {
                            "type": "integer",
                            "enum": [
                                0,
                                1
                            ]
                        },
                        "right": {
                            "type": "integer",
                            "enum": [
                                0,
                                1
                            ]
                        }
                    }
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "cyclomatic_complexity": {
            "description": "Examine the complexity of your application.",
            "properties": {
                "value": {
                    "type": "integer"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "duplicate_key": {
            "description": "Prevents defining duplicate keys in object literals and classes.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "empty_constructor_needs_parens": {
            "description": "Requires constructors with no parameters to include the parens.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "indentation": {
            "description": " This rule imposes a standard number of spaces to be used for indentation. Since whitespace is significant in CoffeeScript, it's critical that a project chooses a standard indentation format and stays consistent. Other roads lead to darkness.",
            "properties": {
                "value": {
                    "type": "integer",
                    "enum": [
                        2,
                        4
                    ]
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "line_endings": {
            "description": "This rule ensures your project uses only windows or unix line endings.",
            "properties": {
                "value": {
                    "type": "string",
                    "enum": [
                        "unix",
                        "windows"
                    ]
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "max_line_length": {
            "description": "This rule imposes a maximum line length on your code.",
            "properties": {
                "value": {
                    "type": "integer"
                },
                "limitComments": {
                    "type": "boolean"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "missing_fat_arrows": {
            "description": "Warns when you use `this` inside a function that wasn't defined with a fat arrow. This rule does not apply to methods defined in a class, since they have `this` bound to the class instance (or the class itself, for class methods).",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "newlines_after_classes": {
            "description": "Checks the number of newlines between classes and other code.",
            "properties": {
                "value": {
                    "type": "integer"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_backticks": {
            "description": "Backticks allow snippets of JavaScript to be embedded in CoffeeScript. While some folks consider backticks useful in a few niche circumstances, they should be avoided because so none of JavaScript's \"bad parts\", like with and eval, sneak into CoffeeScript.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_debugger": {
            "description": "This rule detects the `debugger` statement.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_empty_param_list": {
            "description": "This rule prohibits empty parameter lists in function definitions.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_implicit_braces": {
            "description": "This rule prohibits implicit braces when declaring object literals. Implicit braces can make code more difficult to understand, especially when used in combination with optional parenthesis.",
            "properties": {
                "strict": {
                    "type": "boolean"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_implicit_parens": {
            "description": "This rule prohibits implicit parens on function calls.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_interpolation_in_single_quotes": {
            "description": "This rule prohibits string interpolation in a single quoted string.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_plusplus": {
            "description": "This rule forbids the increment and decrement arithmetic operators. Some people believe the ++ and -- to be cryptic and the cause of bugs due to misunderstandings of their precedence rules.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_stand_alone_at": {
            "description": "This rule checks that no stand alone @ are in use, they are discouraged.",
            "type": "object",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_tabs": {
            "description": "This rule forbids tabs in indentation. Enough said.",
            "type": "object",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_throwing_strings": {
            "description": " This rule forbids throwing string literals or interpolations. While JavaScript (and CoffeeScript by extension) allow any expression to be thrown, it is best to only throw  Error objects, because they contain valuable debugging information like the stack trace.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_trailing_semicolons": {
            "description": "This rule prohibits trailing semicolons, since they are needless cruft in CoffeeScript.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_trailing_whitespace": {
            "description": "This rule forbids trailing whitespace in your code, since it is needless cruft.",
            "properties": {
                "allowed_in_comments": {
                    "type": "boolean"
                },
                "allowed_in_empty_lines": {
                    "type": "boolean"
                }
            },
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_unnecessary_double_quotes": {
            "description": "This rule prohibits double quotes unless string interpolation is used or the string contains single quotes.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "no_unnecessary_fat_arrows": {
            "description": "Disallows defining functions with fat arrows when `this` is not used within the function. ",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "non_empty_constructor_needs_parens": {
            "description": "Requires constructors with parameters to include the parens.",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        },
        "space_operators": {
            "description": "This rule enforces that operators have space around them. ",
            "allOf": [
                {
                    "$ref": "#/definitions/base"
                }
            ]
        }
    },
    "additionalProperties": true
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "A schema for Umbraco's package.manifest files.",
    "definitions": {
        "editor": {
            "description": "This describes details about the editor",
            "type": "object",
            "properties": {
                "view": {
                    "description": "This is the full path to the HTML view for your property editor",
                    "type": "string"
                },
                "hideLabel": {
                    "description": "If set to true this hides the label for the property editor when used in Umbraco on a document type",
                    "type": "boolean"
                },
                "valueType": {
                    "description": "This is the type of data you want your property editor to save to Umbraco",
                    "type": "string",
                    "enum": [
                        "STRING",
                        "JSON",
                        "DATETIME",
                        "TEXT",
                        "INT"
                    ]
                },
                "validation": {
                    "description": "Object describing required validators on the editor",
                    "type": "object"
                },
                "isReadOnly": {
                    "description": "If set to true this makes the property editor read only",
                    "type": "boolean",
                    "default": false
                }
            },
            "additionalProperties": false
        },
        "editors": {
            "type": "object",
            "properties": {
                "alias": {
                    "description": "This must be a unique alias to your property editor",
                    "type": "string"
                },
                "defaultConfig": {
                    "description": "Provides a collection of default configuration values, in cases the property editor is not configured or is used a parameter editor, which doesnt allow configuration. The object is a key/value collection and must match the prevalue fields keys.",
                    "type": "object",
                    "minProperties": 1
                },
                "editor": {
                    "$ref": "#/definitions/editor"
                },
                "isParameterEditor": {
                    "description": "Enables the property editor as a macro parameter editor can be true/false",
                    "type": "boolean",
                    "default": false
                },
                "name": {
                    "description": "The friendly name of the property editor, shown in the Umbraco backoffice",
                    "type": "string"
                }
            },
            "required": [
                "name",
                "alias",
                "editor"
            ]
        },
        "preValues": {
            "type": "object",
            "properties": {
                "prevalues": {
                    "description": "This is an object that stores an array of prevalue fields or options to configure yout property editor",
                    "type": "object",
                    "properties": {
                        "fields": {
                            "$ref": "#/definitions/fields"
                        }
                    }
                }
            }
        },
        "fields": {
            "description": "This is the collection of prevalue fields",
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "key": {
                        "description": "A unique key for the prevalue field",
                        "type": "string",
                        "minLength": 1
                    },
                    "label": {
                        "description": "The user friendly label for the prevalue",
                        "type": "string"
                    },
                    "description": {
                        "description": "A more detailed description for the user",
                        "type": "string"
                    },
                    "view": {
                        "description": "The type of editor to use for this prevalue field",
                        "type": "string"
                    },
                    "validation": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "type": {
                                    "type": "string"
                                }
                            }
                        }
                    }
                },
                "minProperties": 1
            },
            "minItems": 1
        }
    },
    "type": "object",
    "properties": {
        "javascript": {
            "description": "A list of Javascript files with full path to load for your property editor",
            "type": "array",
            "items": {
                "type": "string"
            },
            "_uniqueItems": true
        },
        "css": {
            "description": "A list of CSS files with full path to load for your property editor",
            "type": "array",
            "items": {
                "type": "string"
            },
            "_uniqueItems": true
        },
        "propertyEditors": {
            "description": "Returns an array of editor objects, each object specifies an editor to make available to data types as an editor component. These editors are primarily property editors for content, media and members, but can also be made available as a macro parameter editor.",
            "type": "array",
            "items": {
                "allOf": [
                    {
                        "$ref": "#/definitions/editors"
                    },
                    {
                        "$ref": "#/definitions/preValues"
                    }
                ]
            },
            "minItems": 1
        },
        "parameterEditors": {
            "description": "Returns an array of editor objects, each object specifies an editor to make available to macro parameters as an editor component. These editors work solely as parameter editors, and will not show up on the property editors list.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/editors"
            },
            "minItems": 1
        }
    }
}

