                    "linie",
                    "kurs",
                    "route",
                    "prio",
                    "zuglaenge",
                    "richtung",
                    "abw"
                ],
                "type": "object"
            },
            "type": "array"
        },
        "timestamp": {
            "_format": "date-time",
