            "items": {
                "properties": {
                    "name": {
                        "description": "Variable name.",
                        "type": "string"
                    },
                    "value": {
                        "description": "Variable value.",
                        "type": "string"
                    }
                },
                "required": [
                    "name",
                    "value"
                ],
                "type": "object"
            },
            "type": "array"
        }
    },
    "required": [
        "domainUUID",
        "unitNr",
        "timestamp",
        "tx"
    ],
    "type": "object"
}

